            mediaType: string;
            caption?: string;
            audioDurationSeconds?: number;
        },
        beforeSend: RemoteProxy<{record: (ids: readonly MessageId[]) => Promise<void>}>,
    ): Promise<readonly MessageId[]> {
        if (!/^[a-f0-9]{64}$/u.test(token) || beforeSend === undefined)
            throw new Error('Invalid prepared file send');
        // Validate and snapshot before awaiting receiver lookup or consuming the token.
        if (
            metadata === null ||
            typeof metadata !== 'object' ||
            (metadata.audioDurationSeconds !== undefined &&
                (metadata.mediaType !== 'audio/mp4' ||
                    typeof metadata.audioDurationSeconds !== 'number' ||
                    !Number.isFinite(metadata.audioDurationSeconds) ||
                    metadata.audioDurationSeconds <= 0 ||
                    metadata.audioDurationSeconds > 10000)) ||
            typeof metadata.fileName !== 'string' ||
            !metadata.fileName ||
            new TextEncoder().encode(metadata.fileName).byteLength > 1024 ||
            /[\x00-\x1f\x7f/\\\u202a-\u202e\u2066-\u2069]/u.test(metadata.fileName) ||
            metadata.fileName === '.' ||
            metadata.fileName === '..' ||
            typeof metadata.mediaType !== 'string' ||
            metadata.mediaType.length > 127 ||
            !/^[a-z0-9!#$&^_.+-]+\/[a-z0-9!#$&^_.+-]+$/iu.test(metadata.mediaType) ||
