                break;
            }
            default:
                throw new Error('Unsupported prepared file receiver');
        }
        const fileData = registry.claim(token, chat);
        const ids = await this.sendStoredFileWithIds(
            {
                type: 'stored-file',
                audioDurationSeconds: metadata.audioDurationSeconds,
                fileData,
                fileName: metadata.fileName,
                mediaType: metadata.mediaType,
                caption: metadata.caption,
