            dimensions.height < 1 ||
            dimensions.width > 8192 ||
            dimensions.height > 8192 ||
            !Number.isSafeInteger(thumbnail.width) ||
            !Number.isSafeInteger(thumbnail.height) ||
            thumbnail.width < 1 ||
            thumbnail.height < 1 ||
            thumbnail.width > 512 ||
            thumbnail.height > 512
        )
            throw new Error('Invalid prepared image dimensions');
        metadata = {...metadata, dimensions: {...dimensions}, thumbnailDimensions: {...thumbnail}};
        const registry = this._services.file.preparedFiles;
        if (registry === undefined) throw new Error('Prepared files are unavailable');
        const receiver = (await this._conversation.get().controller.receiver()).get();
        let chat: string;
        switch (receiver.type) {
            case ReceiverType.CONTACT:
