                    throw new Error('Prepared file send not permitted');
                const creator =
                    receiver.view.creator === 'me'
                        ? this._services.device.identity.string
                        : receiver.view.creator.get().view.identity;
                chat = `g:${creator}:${u64ToHexLe(receiver.view.groupId)}`;
                break;
