        metadata: Omit<SendStoredVideoInformation, 'type' | 'fileData' | 'thumbnailFileData'>,
        beforeSend: RemoteProxy<{record: (ids: readonly MessageId[]) => Promise<void>}>,
    ): Promise<readonly MessageId[]> {
        if (
            !/^[a-f0-9]{64}$/u.test(token) ||
            beforeSend === undefined ||
            (thumbnailToken !== undefined &&
                (!/^[a-f0-9]{64}$/u.test(thumbnailToken) || thumbnailToken === token))
        )
