        metadata = validatePreparedVideoMetadata(metadata, thumbnailToken !== undefined);
        const registry = this._services.file.preparedFiles;
        if (registry === undefined) throw new Error('Prepared files are unavailable');
        const receiver = (await this._conversation.get().controller.receiver()).get();
        let chat: string;
        switch (receiver.type) {
            case ReceiverType.CONTACT:
                chat = `c:${receiver.view.identity}`;
                break;
            case ReceiverType.GROUP: {
