    /** Worker-local only: StoredFileHandle contains a secret wrapper that must not cross proxies. */
    public async sendStoredFileWithIds(
        prepared:
            | SendStoredFileInformation
            | SendStoredImageInformation
            | SendStoredVideoInformation,
        beforeSend?: {record: (ids: readonly MessageId[]) => Promise<unknown>},
    ): Promise<readonly MessageId[]> {
        const {crypto} = this._services;
        if (
            !Number.isSafeInteger(prepared.fileData.unencryptedByteCount) ||
            prepared.fileData.unencryptedByteCount < 0 ||
            prepared.fileData.unencryptedByteCount > import.meta.env.MAX_FILE_MESSAGE_BYTES ||
            !prepared.fileName ||
            new TextEncoder().encode(prepared.fileName).byteLength > 1024 ||
            !/^[a-z0-9!#$&^_.+-]+\/[a-z0-9!#$&^_.+-]+$/iu.test(prepared.mediaType) ||
            (prepared.caption !== undefined &&
                new TextEncoder().encode(prepared.caption).byteLength >
                    import.meta.env.MAX_TEXT_MESSAGE_BYTES)
        ) {
            throw new Error('Invalid prepared file metadata');
        }
        if (prepared.type === 'stored-video') {
            validatePreparedVideoMetadata(
                {
                    fileName: prepared.fileName,
                    mediaType: prepared.mediaType,
                    caption: prepared.caption,
                    durationSeconds: prepared.durationSeconds,
                    dimensions: prepared.dimensions,
                    thumbnailMediaType: prepared.thumbnailMediaType,
                    thumbnailDimensions: prepared.thumbnailDimensions,
                },
                prepared.thumbnailFileData !== undefined,
            );
            if (prepared.fileData.unencryptedByteCount < 1) throw new Error('Empty prepared video');
            if (
                prepared.thumbnailFileData !== undefined &&
                (prepared.thumbnailFileData.fileId === prepared.fileData.fileId ||
                    !Number.isSafeInteger(prepared.thumbnailFileData.unencryptedByteCount) ||
                    prepared.thumbnailFileData.unencryptedByteCount < 1 ||
                    prepared.thumbnailFileData.unencryptedByteCount >
                        import.meta.env.MAX_FILE_MESSAGE_BYTES)
            )
                throw new Error('Invalid prepared video thumbnail handle');
        } else if (prepared.type === 'stored-image') {
            const {width, height} = prepared.dimensions;
            const thumbnail = prepared.thumbnailDimensions;
            if (
                (prepared.mediaType !== 'image/png' &&
                    prepared.mediaType !== 'image/jpeg' &&
                    prepared.mediaType !== 'image/gif' &&
                    prepared.mediaType !== 'image/webp') ||
                (prepared.thumbnailMediaType !== 'image/png' &&
                    prepared.thumbnailMediaType !== 'image/jpeg') ||
                !Number.isSafeInteger(width) ||
                !Number.isSafeInteger(height) ||
                width < 1 ||
                height < 1 ||
                width > 8192 ||
                height > 8192 ||
                !Number.isSafeInteger(thumbnail.width) ||
                !Number.isSafeInteger(thumbnail.height) ||
                thumbnail.width < 1 ||
                thumbnail.height < 1 ||
                thumbnail.width > 512 ||
                thumbnail.height > 512 ||
                !Number.isSafeInteger(prepared.thumbnailFileData.unencryptedByteCount) ||
                prepared.thumbnailFileData.unencryptedByteCount < 1 ||
                prepared.thumbnailFileData.unencryptedByteCount >
                    import.meta.env.MAX_FILE_MESSAGE_BYTES ||
                prepared.fileData.fileId === prepared.thumbnailFileData.fileId
            )
                throw new Error('Invalid prepared image metadata');
        } else if (prepared.type === 'stored-file' && prepared.audioDurationSeconds !== undefined) {
            if (
                prepared.mediaType !== 'audio/mp4' ||
                !Number.isFinite(prepared.audioDurationSeconds) ||
                prepared.audioDurationSeconds <= 0 ||
                prepared.audioDurationSeconds > 10000
            )
                throw new Error('Invalid prepared audio metadata');
        } else if (prepared.type !== 'stored-file') {
            throw new Error('Invalid prepared media type');
        }
        const common = {
            fileData: prepared.fileData,
            fileSize: prepared.fileData.unencryptedByteCount,
            fileName: prepared.fileName,
            mediaType: prepared.mediaType,
            caption: prepared.caption?.length === 0 ? undefined : prepared.caption,
            encryptionKey: wrapRawBlobKey(
                crypto.randomBytes(new Uint8Array(NACL_CONSTANTS.KEY_LENGTH)),
            ),
        };
        const fragment: OutboundMessageInitFragment =
            prepared.type === 'stored-video'
                ? {
                      ...common,
                      type: 'video',
                      duration: prepared.durationSeconds,
                      dimensions: {...prepared.dimensions},
                      thumbnailMediaType: prepared.thumbnailMediaType,
                      thumbnailFileData: prepared.thumbnailFileData,
                  }
                : prepared.type === 'stored-image'
                  ? {
                        ...common,
                        type: 'image',
                        renderingType: ImageRenderingType.REGULAR,
                        animated: false,
                        dimensions: {...prepared.dimensions},
                        thumbnailMediaType: prepared.thumbnailMediaType,
                        thumbnailFileData: prepared.thumbnailFileData,
                    }
                  : prepared.audioDurationSeconds !== undefined
                    ? {...common, type: 'audio', duration: prepared.audioDurationSeconds}
                    : {...common, type: 'file'};
        const fragments = [fragment];
        return await this._sendFragmentsWithIds(fragments, beforeSend);
    }

    public async sendMessage(messageEventDetail: Remote<SendMessageEventDetail>): Promise<void> {
        await this.sendMessageWithIds(messageEventDetail);
    }

    /** Await durable ID recording before the first local message or protocol task is created. */
    public async sendMessageWithIds(
        messageEventDetail: Remote<SendMessageEventDetail>,
        beforeSend?: RemoteProxy<{record: (ids: readonly MessageId[]) => Promise<void>}>,
    ): Promise<readonly MessageId[]> {
        const {crypto} = this._services;

        let outgoingMessageInitFragments: OutboundMessageInitFragment[] = [];
        switch (messageEventDetail.type) {
            case 'text':
                outgoingMessageInitFragments = [
                    {
                        type: 'text',
                        text: messageEventDetail.text,
                        quotedMessageId: messageEventDetail.quotedMessageId,
                    },
                ];
                break;
            case 'files':
                outgoingMessageInitFragments = await this._prepareFileBasedMessageInitFragments(
                    messageEventDetail.files,
                    this._log,
                );
                break;
            case 'poll':
                outgoingMessageInitFragments = [
                    {
                        type: 'poll',
                        announceType: messageEventDetail.announceType,
                        answerType: messageEventDetail.answerType,
                        description: messageEventDetail.description,
                        displayMode: messageEventDetail.displayMode,
                        pollCreatorIdentity: this._services.device.identity.string,
                        pollId: randomPollId(this._services.crypto),
                        pollState: messageEventDetail.pollState,
                        choicesType: PollChoicesType.TEXT,
                        choices: messageEventDetail.choices.map((choice) => ({
                            description: choice.description,
                            choiceId: choice.choiceId,
                            sortKey: choice.choiceId,
                            participantVotes: [],
                        })),
                        participants: [],
                    },
                ];
                break;
            default:
                unreachable(messageEventDetail);
        }

        return await this._sendFragmentsWithIds(outgoingMessageInitFragments, beforeSend);
    }

    private async _sendFragmentsWithIds(
        outgoingMessageInitFragments: OutboundMessageInitFragment[],
        beforeSend?: {record: (ids: readonly MessageId[]) => Promise<unknown>},
    ): Promise<readonly MessageId[]> {
        const {crypto} = this._services;
        const messages = outgoingMessageInitFragments.map((init) => ({
            init,
            id: randomMessageId(crypto),
        }));
        const ids = messages.map(({id}) => id);
        await beforeSend?.record([...ids]);
        for (const {init, id} of messages) {
            this._log.debug(`Send ${init.type} message with id ${id}`);

            await this._conversation.get().controller.addMessage.fromLocal({
                direction: MessageDirection.OUTBOUND,
                id,
                createdAt: new Date(),
                ...init,
            });
        }
        return ids;
    }

    /** @inheritdoc */
    public async sendPollCloseMessage(pollLookup: PollLookup): Promise<void> {
        if (pollLookup.pollCreatorIdentity !== this._services.device.identity.string) {
            this._log.error('Cannot close a poll where the user is not the creator');
            return;
        }

        const poll = this._conversation
            .get()
            .controller.getMessageByPollId(
                pollLookup.pollCreatorIdentity,
                pollLookup.pollId,
                PollMessageType.POLL_CREATED,
            );
        assert(
            poll !== undefined && poll.ctx === MessageDirection.OUTBOUND,
            'Poll to be closed must exist within the given conversation',
        );

        // If the poll is already closed, do nothing.
        if (poll.get().view.pollState === PollState.CLOSED) {
            this._log.debug(
                'Trying to close a poll that was already closed. Returning without adding a new message',
            );
            return;
        }
        // Close the current poll.
        poll.get().controller.close.direct();

        const {view: pollView} = poll.get();

        const {participants, votes} = poll.get().controller.getParticipantsAndVotes();

        await this._conversation.get().controller.addMessage.fromLocal({
            direction: MessageDirection.OUTBOUND,
            pollState: PollState.CLOSED,
            id: randomMessageId(this._services.crypto),
            announceType: pollView.announceType,
            answerType: pollView.answerType,
            createdAt: new Date(),
            description: pollView.description,
            displayMode: pollView.displayMode,
            pollCreatorIdentity: this._services.device.identity.string,
            pollId: pollLookup.pollId,
            participants,
            choicesType: pollView.choicesType,
            choices: pollView.choices.map((choice, index) => ({
                choiceId: choice.choiceId,
                description: choice.description,
                // Unwrap is fine since `getParticipantsAndVotes` guarantees that this exists.
                participantVotes: unwrap(votes[index]),
                sortKey: choice.sortKey,
                totalAmountVotes: choice.totalAmountVotes,
            })),
            type: 'poll',
        });
    }

    /** @inheritdoc */
    public setCurrentViewportMessages(messageIds: Set<MessageId | StatusMessageId>): void {
        this._currentViewportMessagesStore.set(messageIds);
    }

    public async unarchive(): Promise<void> {
        return await this._conversation
            .get()
            .controller.updateVisibility.fromLocal(ConversationVisibility.SHOW);
    }

    public async unpin(): Promise<void> {
        return await this._conversation
            .get()
            .controller.updateVisibility.fromLocal(ConversationVisibility.SHOW);
    }

    private async _joinCall<TIntent = 'join' | 'join-or-create'>(
        intent: TIntent,
        cancel: RemoteAbortListener<unknown>,
    ): Promise<
        TIntent extends 'join'
            ? OngoingGroupCallViewModelBundle | undefined
            : OngoingGroupCallViewModelBundle
    > {
        const receiver = this._conversation.get().controller.receiver();
        assert(receiver.type === ReceiverType.GROUP);
        const ongoing = await receiver.get().controller.joinCall(intent, cancel);
        if (ongoing === undefined) {
            return undefined as TIntent extends 'join'
                ? OngoingGroupCallViewModelBundle | undefined
                : OngoingGroupCallViewModelBundle;
        }
        return getOngoingGroupCallViewModelBundle(this._services, ongoing);
    }

    /**
     * Generate outgoing message init fragments based on the files. These files may be sent as raw
     * files or as media files, depending on the media type.
     */
    private async _prepareFileBasedMessageInitFragments(
        files: SendFileBasedMessageInformation['files'],
        log?: Logger,
    ): Promise<OutboundMessageInitFragment[]> {
        const {crypto, file} = this._services;

        const outgoingMessageInitFragments: OutboundMessageInitFragment[] = [];

        // If more than 1 file is being sent, set a correlation ID
        const correlationId = files.length > 1 ? randomString(crypto, 32) : undefined;

        for (const fileInfo of files) {
            // Generate random blob encryption key for the blobs (which will be encrypted and
            // uploaded by the outgoing conversation message task)
            const encryptionKey = wrapRawBlobKey(
                crypto.randomBytes(new Uint8Array(NACL_CONSTANTS.KEY_LENGTH)),
            );

            const commonFileProperties = {
                caption: fileInfo.caption?.length === 0 ? undefined : fileInfo.caption,
                correlationId,
                encryptionKey,
            };

            const thumbnailFileData =
                fileInfo.thumbnailBytes !== undefined
                    ? await file.store(fileInfo.thumbnailBytes)
                    : undefined;

            // Determine message type based on media type
            let messageType: MediaBasedMessageType = getMessageType(fileInfo);

            for (;;) {
                switch (messageType) {
                    case MessageType.FILE:
                        outgoingMessageInitFragments.push({
                            type: 'file',
                            ...commonFileProperties,
                            fileName: fileInfo.fileName,
                            fileSize: fileInfo.fileSize,
                            mediaType: fileInfo.mediaType,
                            fileData: await file.store(fileInfo.bytes),
                        });
                        break;
                    case MessageType.VIDEO: {
                        const transcodingResult = await transcodeVideoAndSetProperties(
                            fileInfo.bytes,
                            this._services.model.user.mediaSettings.get().view.videoQuality,
                            log,
                        );

                        if (transcodingResult === undefined) {
                            log?.debug('Could not transcode video, sending the message as file');
                            messageType = MessageType.FILE;
                            continue;
                        }

                        const {bytes, ...rest} = transcodingResult;
                        outgoingMessageInitFragments.push({
                            ...commonFileProperties,
                            ...rest,
                            fileData: await file.store(bytes),
                            dimensions: fileInfo.dimensions,
                            thumbnailMediaType: fileInfo.thumbnailMediaType,
                            thumbnailFileData,
                        });
                        break;
                    }
                    case MessageType.AUDIO: {
                        const transcodingResult = await transcodeAudioAndSetProperties(
                            fileInfo.bytes,
                            log,
                        );

                        if (transcodingResult === undefined) {
                            log?.debug('Could not transcode audio, sending the message as file');
                            messageType = MessageType.FILE;
                            continue;
                        }

                        const {bytes, ...rest} = transcodingResult;
                        outgoingMessageInitFragments.push({
                            ...commonFileProperties,
                            ...rest,
                            fileData: await file.store(bytes),
                        });
                        break;
                    }
                    case MessageType.IMAGE:
                        outgoingMessageInitFragments.push({
                            type: 'image',
                            ...commonFileProperties,
                            fileName: fileInfo.fileName,
                            fileSize: fileInfo.fileSize,
                            mediaType: fileInfo.mediaType,
                            fileData: await file.store(fileInfo.bytes),
                            renderingType: ImageRenderingType.REGULAR,
                            animated: false, // TODO(DESK-1115)
                            dimensions: fileInfo.dimensions,
                            thumbnailMediaType: fileInfo.thumbnailMediaType,
                            thumbnailFileData,
                        });
                        break;
                    default:
                        unreachable(messageType);
                }
                break;
            }
        }

        return outgoingMessageInitFragments;
    }
}

function validatePreparedVideoMetadata(
    metadata: Omit<SendStoredVideoInformation, 'type' | 'fileData' | 'thumbnailFileData'>,
    hasThumbnail: boolean,
): typeof metadata {
    if (
        !metadata ||
        typeof metadata !== 'object' ||
        Object.keys(metadata).some(
            (key) =>
                ![
                    'fileName',
                    'mediaType',
                    'caption',
                    'durationSeconds',
                    'dimensions',
                    'thumbnailMediaType',
                    'thumbnailDimensions',
                ].includes(key),
        ) ||
        typeof metadata.fileName !== 'string' ||
        !metadata.fileName ||
        metadata.fileName === '.' ||
        metadata.fileName === '..' ||
        /[\x00-\x1f\x7f/\\\u202a-\u202e\u2066-\u2069]/u.test(metadata.fileName) ||
        new TextEncoder().encode(metadata.fileName).byteLength > 1024 ||
        metadata.mediaType !== 'video/mp4' ||
        typeof metadata.durationSeconds !== 'number' ||
        !Number.isFinite(metadata.durationSeconds) ||
        metadata.durationSeconds <= 0 ||
        metadata.durationSeconds > 10000 ||
        (metadata.caption !== undefined &&
            (typeof metadata.caption !== 'string' ||
                new TextEncoder().encode(metadata.caption).byteLength >
                    import.meta.env.MAX_TEXT_MESSAGE_BYTES))
    )
        throw new Error('Invalid prepared video metadata');
    const dimensions = metadata.dimensions,
        thumbnail = metadata.thumbnailDimensions;
    if (
        !dimensions ||
        ![dimensions.width, dimensions.height].every(
            (value) => Number.isSafeInteger(value) && value > 0 && value <= 8192,
        )
    )
        throw new Error('Invalid prepared video dimensions');
    if (
        hasThumbnail
            ? !thumbnail ||
              ![thumbnail.width, thumbnail.height].every(
                  (value) => Number.isSafeInteger(value) && value > 0 && value <= 512,
              ) ||
              (metadata.thumbnailMediaType !== 'image/png' &&
                  metadata.thumbnailMediaType !== 'image/jpeg')
            : metadata.thumbnailDimensions !== undefined ||
              metadata.thumbnailMediaType !== undefined
    )
        throw new Error('Invalid prepared video thumbnail metadata');
    return {
        ...metadata,
        dimensions: {...dimensions},
        ...(thumbnail === undefined ? {} : {thumbnailDimensions: {...thumbnail}}),
    };
}

